function bindAuth(i){$(".register-webauth").on("click",function(){navigator.credentials&&postJson(i+"/passkey/register_option",{},t=>{t=t.data;t.challenge=Base64.toBuffer(t.challenge),t.user.id=Base64.toBuffer(t.user.id),navigator.credentials.create({publicKey:t}).then(t=>{var e=t.response;postJson(i+"/passkey/register",{credential:{id:t.id,clientDataJSON:Base64.encode(e.clientDataJSON),attestationObject:Base64.encode(e.attestationObject),publicKeyAlgorithm:e.getPublicKeyAlgorithm()}})}).catch(console.error)})}).toggle(!!navigator.credentials)}function bindBulletin(){$(document).on("click",".bulletin-item .title",function(){$(this).closest(".bulletin-item").toggleClass("min")}).on("click",".bulletin-item .content a",function(t){var e,i=$(this);i.attr("target")||"#"===(e=i.attr("href"))||!e||0<=e.indexOf("javascript:")||(t.stopPropagation(),t.preventDefault(),window.location.href=i.attr("href"))})}